const app = document.querySelector("#app");
const company = "Noorani Hajj & Umrah (Pvt) Ltd";
let selectedCurrency = "USD";
const rates = { USD: 1, PKR: 280, SAR: 3.75, GBP: 0.79 };
const money = value => new Intl.NumberFormat("en-US", { style: "currency", currency: selectedCurrency, maximumFractionDigits: 0 }).format(value * rates[selectedCurrency]);
const hotels = [
  { id: "makkah-clock", name: "Makkah Clock Royal Tower", city: "Makkah", distance: "0.4 km", rating: "4.7", rent: 185, image: "https://images.unsplash.com/photo-1566073771259-6a8506099945?auto=format&fit=crop&w=1200&q=80", facilities: "Shuttle service, family rooms, restaurant" },
  { id: "madinah-view", name: "Madinah View Suites", city: "Madinah", distance: "0.7 km", rating: "4.5", rent: 120, image: "https://images.unsplash.com/photo-1551882547-ff40c63fe5fa?auto=format&fit=crop&w=1200&q=80", facilities: "Breakfast, accessible rooms, Wi-Fi" },
  { id: "safa-residence", name: "Safa Residence", city: "Makkah", distance: "1.2 km", rating: "4.3", rent: 95, image: "https://images.unsplash.com/photo-1564501049412-61c2a3083791?auto=format&fit=crop&w=1200&q=80", facilities: "Transport, laundry, prayer room" }
];
const flights = [
  { airline: "Saudia", route: "ISB → JED", duration: "7h 20m", stops: "1 stop", fare: 820 },
  { airline: "Qatar Airways", route: "LHE → JED", duration: "8h 10m", stops: "1 stop", fare: 760 },
  { airline: "Emirates", route: "KHI → MED", duration: "7h 45m", stops: "1 stop", fare: 895 }
];
const packages = [
  { id: "umrah-economy", title: "Essential Umrah Package", type: "Umrah", days: 10, price: 2250, image: "https://images.unsplash.com/photo-1564769662533-4f00a87b4056?auto=format&fit=crop&w=1200&q=80", description: "A carefully planned package with accommodation, transfers, guidance, and time for worship.", includes: "Visa assistance, hotels, airport transfers, Ziyarat, group support" },
  { id: "umrah-family", title: "Family Umrah Package", type: "Umrah", days: 14, price: 3200, image: "https://images.unsplash.com/photo-1591604129939-f1efa4d9f7fa?auto=format&fit=crop&w=1200&q=80", description: "Comfortable family arrangements with flexible transport and nearby accommodation.", includes: "Family rooms, transfers, guided Ziyarat, support coordinator" },
  { id: "hajj-premium", title: "Hajj Premium Package", type: "Hajj", days: 21, price: 5800, image: "https://images.unsplash.com/photo-1548013146-72479768bada?auto=format&fit=crop&w=1200&q=80", description: "End-to-end Hajj planning with experienced guidance and hospitality support.", includes: "Accommodation, transport, meals, Hajj guidance, on-ground support" }
];
const articles = [
  { id: "hajj-guide", title: "A practical Hajj guide for first-time pilgrims", category: "Hajj guide", image: "https://images.unsplash.com/photo-1591604129939-f1efa4d9f7fa?auto=format&fit=crop&w=1200&q=80", text: "Hajj is a journey of worship, patience, and preparation. Nooranis help pilgrims prepare documents, understand each stage, and travel with an organised plan." },
  { id: "umrah-prayers", title: "Prayers and preparation for Umrah", category: "Umrah guide", image: "https://images.unsplash.com/photo-1564769625905-50e93615e769?auto=format&fit=crop&w=1200&q=80", text: "Begin with sincere intention, learn the essential rites, prepare comfortable clothing and medication, and keep a simple schedule that leaves room for prayer and rest." },
  { id: "noorani-hospitality", title: "Hospitality built around trust", category: "About Nooranis", image: "https://images.unsplash.com/photo-1551882547-ff40c63fe5fa?auto=format&fit=crop&w=1200&q=80", text: "Nooranis coordinate accommodation, transport, Ziyarat, and support so families can focus on their pilgrimage. Clear information and dependable assistance guide every arrangement." }
];
const services = [
  { title: "Ziyarat and local visits", description: "Plan visits to significant locations in Makkah, Madinah, and nearby landmarks with organised transport." },
  { title: "Accessible pilgrimage support", description: "Request wheelchair-friendly transport, accessible rooms, mobility assistance, and tailored coordination." },
  { title: "Accommodation and hospitality", description: "Choose hotels by distance, facilities, room type, and daily estimated rent." }
];
const href = (path, text) => `<a class="text-link" href="#${path}">${text}</a>`;
const card = (item, path, meta) => `<article class="card"><a class="card-image-link" href="#${path}"><div class="card-image" style="background-image:url('${item.image}')"></div></a><div class="card-body"><div class="meta">${meta}</div><h3><a href="#${path}">${item.title || item.name}</a></h3><p>${item.description || item.facilities || "Comfortable arrangements with clear support from Nooranis."}</p>${href(path, "View complete details →")}</div></article>`;
const shell = content => { app.innerHTML = `<section class="section"><div class="currency-switcher"><label for="currency">Currency</label><select id="currency"><option value="USD" ${selectedCurrency === "USD" ? "selected" : ""}>USD</option><option value="PKR" ${selectedCurrency === "PKR" ? "selected" : ""}>PKR</option><option value="SAR" ${selectedCurrency === "SAR" ? "selected" : ""}>SAR</option><option value="GBP" ${selectedCurrency === "GBP" ? "selected" : ""}>GBP</option></select></div>${content}</section><footer><strong>${company}</strong><p>Nooranis help pilgrims plan Hajj and Umrah with confidence.</p><a href="mailto:info@noorani.com.pk">info@noorani.com.pk</a></footer>`; const picker = document.querySelector("#currency"); picker.addEventListener("change", event => { selectedCurrency = event.target.value; render(); }); };
function home() { shell(`<section class="hero"><div class="hero-copy"><div class="eyebrow">Nooranis pilgrimage services</div><h1>Travel with peace of mind for Hajj and Umrah.</h1><p>Compare flights, find hotels close to the holy sites, and choose a complete package with dependable support.</p><div class="hero-actions"><a class="button" href="#packages">Explore packages</a><a class="button secondary" href="#flights">Plan a flight</a></div></div><div class="hero-art"><span>Every pilgrimage begins with a peaceful first step.</span></div></section><div class="quick-grid"><a class="quick-card" href="#flights"><strong>Flight Planning</strong><span>Find flights that fit your plans</span></a><a class="quick-card" href="#hotels"><strong>Nearby Hotels</strong><span>Stay close to the holy sites</span></a><a class="quick-card" href="#packages"><strong>Pilgrimage Packages</strong><span>Get support for your pilgrimage</span></a></div><div class="section-heading"><h2>Complete packages</h2>${href("packages", "See all packages")}</div><div class="card-grid">${packages.map(p => card(p, `package/${p.id}`, `${p.type} · ${p.days} days`)).join("")}</div><div class="section-heading"><h2>Guidance from Nooranis</h2>${href("articles", "Read all articles")}</div><div class="card-grid">${articles.map(a => card(a, `article/${a.id}`, a.category)).join("")}</div>`); }
function packagesPage() { shell(`<a class="back" href="#home">← Home</a><h1>Hajj and Umrah packages</h1><p>Choose a package to view the complete itinerary, inclusions, estimated fare, hotel options, and support services.</p><div class="card-grid">${packages.map(p => card(p, `package/${p.id}`, `${p.type} · from ${money(p.price)}`)).join("")}</div>`); }
function packagePage(id) { const p = packages.find(item => item.id === id); if (!p) return packagesPage(); shell(`<a class="back" href="#packages">← All packages</a><div class="detail-header" style="background-image:linear-gradient(120deg,rgba(18,54,47,.88),rgba(18,54,47,.35)),url('${p.image}')"><div class="eyebrow">${p.type} · ${p.days} days</div><h1>${p.title}</h1><p>${p.description}</p><strong>Estimated from ${money(p.price)}</strong></div><div class="content-columns"><div><h2>Package details</h2><p>${p.includes}.</p><h3>Included support</h3><ul><li>Pre-travel orientation and documentation checklist</li><li>On-ground Nooranis support</li><li>Transport and accommodation coordination</li></ul></div><aside class="booking-box"><h3>Start with this package</h3><p>Dates, traveller count, and currency can be changed before enquiry.</p><a class="button" href="#community">Request this package</a></aside></div>`); }
function flightsPage() { shell(`<a class="back" href="#home">← Home</a><h1>Flight planning</h1><p>Compare flight options for your Hajj or Umrah journey and choose what suits your plans.</p><form class="search-form" onsubmit="event.preventDefault(); document.querySelector('#flight-results').scrollIntoView({behavior:'smooth'})"><label>From <input value="ISB"></label><label>To <input value="JED"></label><label>Travellers <input type="number" value="2" min="1"></label><button class="button">Compare flights</button></form><h2 id="flight-results">Estimated flight options</h2><div class="result-list">${flights.map(f => `<article class="result"><div><strong>${f.airline}</strong><span>${f.route} · ${f.duration} · ${f.stops}</span></div><strong>${money(f.fare)}</strong><a class="text-link" href="#community">Request booking →</a></article>`).join("")}</div><div class="calculator"><h2>Flight cost calculator</h2><p>Plan your travel budget with a simple calculator for estimated flight costs.</p><label>Travellers <input id="traveller-count" type="number" value="2" min="1"></label><strong id="estimate">${money(1640)}</strong></div>`); const count = document.querySelector("#traveller-count"); const estimate = document.querySelector("#estimate"); count.addEventListener("input", () => { estimate.textContent = money(Number(count.value) * 820); }); }
function hotelsPage() { shell(`<a class="back" href="#home">← Home</a><h1>Nearby hotels</h1><p>See hotel distance from holy sites, facilities, real accommodation photos, and estimated rent per day.</p><div class="map-placeholder"><strong>Hotel map</strong><span>Connect a map provider to display live markers and automatic distance highlights.</span>${hotels.map((h, i) => `<i class="map-pin" title="${h.name}" style="left:${20 + i * 28}%;top:${35 + i * 13}%">${i + 1}</i>`).join("")}</div><div class="card-grid">${hotels.map(h => card(h, `hotel/${h.id}`, `${h.city} · ${h.distance} · ${money(h.rent)}/day`)).join("")}</div>`); }
function hotelPage(id) { const h = hotels.find(item => item.id === id); if (!h) return hotelsPage(); shell(`<a class="back" href="#hotels">← All hotels</a><div class="detail-header" style="background-image:linear-gradient(120deg,rgba(18,54,47,.88),rgba(18,54,47,.35)),url('${h.image}')"><div class="eyebrow">${h.city} · ${h.distance} from holy site</div><h1>${h.name}</h1><p>Rated ${h.rating}/5 · Estimated ${money(h.rent)} per day</p></div><h2>Facilities</h2><p>${h.facilities}. Photos and availability must be confirmed by the accommodation provider before booking.</p><a class="button" href="#community">Ask Nooranis about this hotel</a>`); }
function articlesPage() { shell(`<a class="back" href="#home">← Home</a><h1>Articles and guidance</h1><div class="card-grid">${articles.map(a => card(a, `article/${a.id}`, a.category)).join("")}</div>`); }
function articlePage(id) { const a = articles.find(item => item.id === id); if (!a) return articlesPage(); shell(`<a class="back" href="#articles">← All articles</a><div class="detail-header" style="background-image:linear-gradient(120deg,rgba(18,54,47,.88),rgba(18,54,47,.35)),url('${a.image}')"><div class="eyebrow">${a.category}</div><h1>${a.title}</h1></div><article class="prose"><p>${a.text}</p><p>Always follow instructions from qualified scholars, official authorities, and medical professionals. Nooranis can help organise practical travel support.</p></article>`); }
function communityPage() { shell(`<a class="back" href="#home">← Home</a><h1>Join the Noorani community</h1><p>Register your details so Nooranis can share suitable pilgrimage support and community updates.</p><form class="community-form" id="community-form"><label>Full name<input required name="name"></label><label>Identity document<select required name="documentType"><option>CNIC</option><option>NICOP</option><option>Passport</option></select></label><label>Document number<input required name="documentNumber"></label><label>Gender<select name="gender"><option>Male</option><option>Female</option></select></label><label>Age<input name="age" type="number" min="1" max="120" required></label><label>Mobile number<input name="mobile" type="tel" required placeholder="+92"></label><label>Email<input name="email" type="email"></label><label>Languages<input name="languages" placeholder="Urdu, English, Arabic"></label><label>Profession<input name="profession"></label><label>Qualifications<input name="qualifications"></label><label class="full"><input name="consent" type="checkbox" required> I consent to Nooranis processing these details for community and pilgrimage support.</label><button class="button" type="submit">Submit registration</button></form>`); document.querySelector("#community-form").addEventListener("submit", async event => { event.preventDefault(); const form = new FormData(event.currentTarget); const response = await fetch("/api/community", { method: "POST", headers: { "content-type": "application/json" }, body: JSON.stringify(Object.fromEntries(form)) }); event.currentTarget.innerHTML = response.ok ? "<h2>Registration received</h2><p>Thank you. Nooranis will contact you after verifying your details.</p>" : "<p>We could not submit your registration. Please try again.</p>"; }); }
function servicesPage() { shell(`<a class="back" href="#home">← Home</a><h1>Support services</h1><p>Manage and arrange facilities for Ziyarat, transport, accommodation, accessibility, and nearby visits.</p><div class="service-grid">${services.map(s => `<article class="service"><h2>${s.title}</h2><p>${s.description}</p><a class="text-link" href="#community">Request support →</a></article>`).join("")}</div><h2>Nearby help</h2><div class="quick-grid"><a class="quick-card" href="#emergency"><strong>Hospitals and emergency services</strong><span>Important contacts for pilgrims</span></a><a class="quick-card" href="#article/hajj-guide"><strong>Complete Hajj & Umrah guide</strong><span>Written and visual preparation</span></a></div>`); }
function emergencyPage() { shell(`<a class="back" href="#services">← Services</a><h1>Hospitals and emergency services</h1><p>For an immediate emergency, contact local emergency services first. Nooranis support can help coordinate travel assistance.</p><div class="result-list"><div class="result"><strong>Saudi emergency services</strong><a href="tel:997">Ambulance 997</a></div><div class="result"><strong>Police</strong><a href="tel:999">999</a></div><div class="result"><strong>Nooranis support</strong><a href="mailto:info@noorani.com.pk">info@noorani.com.pk</a></div></div>`); }
function render() { const [page, id] = location.hash.slice(1).split("/"); if (page === "packages") return packagesPage(); if (page === "package") return packagePage(id); if (page === "flights") return flightsPage(); if (page === "hotels") return hotelsPage(); if (page === "hotel") return hotelPage(id); if (page === "articles") return articlesPage(); if (page === "article") return articlePage(id); if (page === "community") return communityPage(); if (page === "services") return servicesPage(); if (page === "emergency") return emergencyPage(); home(); }
addEventListener("hashchange", render);
render();
